package com.example.rokidgeminisecretary;import javax.crypto.spec.SecretKeySpec;final class DeviceSecrets {static PhotoVaultCipher photos(){return new PhotoVaultCipher(new SecretKeySpec(new byte[32],"AES"));}static String auditHash(String s)throws Exception{return java.util.HexFormat.of().formatHex(java.security.MessageDigest.getInstance("SHA-256").digest(s.getBytes(java.nio.charset.StandardCharsets.UTF_8)));}}